window.docContents[235].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Behavioral-Equivaleence--Definitions":{"contents":"\n\ndef Aexp.Equiv (a₁ a₂ : Aexp) : Prop :=\n  ∀ (st : State),\n    a₁.eval st = a₂.eval st\n\ntheorem Aexp.equiv_def {a₁ a₂ : Aexp} :\n    a₁.Equiv a₂ ↔ ∀ (st : State), a₁.eval st = a₂.eval st := by rfl\n\n\ndef Bexp.Equiv (b₁ b₂ : Bexp) : Prop :=\n  ∀ (st : State),\n    b₁.eval st = b₂.eval st\n\ntheorem Bexp.equiv_def {b₁ b₂ : Bexp} :\n    b₁.Equiv b₂ ↔ ∀ (st : State), b₁.eval st = b₂.eval st := by rfl\n\n\n\n\nexample : Aexp.Equiv\n    (aexp { X - X })\n    (aexp { 0 }) := by\n  rw [Aexp.equiv_def]\n  intro st\n  simp\n\n\nexample : Bexp.Equiv\n    (bexp { X - X = 0 })\n    (bexp { true }) := by\n  rw [Bexp.equiv_def]\n  intro st\n  simp\n\n\n\n\ndef Com.Equiv (c₁ c₂ : Com) : Prop :=\n    ∀ {st st' : State},\n      (st =[ c₁ ]=> st') ↔ (st =[ c₂ ]=> st')\n\ntheorem Com.equiv_def {c₁ c₂ : Com} : c₁.Equiv c₂ ↔\n    ∀ {st st' : State}, (st =[ c₁ ]=> st') ↔ (st =[ c₂ ]=> st') := by rfl\n\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Behavioral Equivaleence","header":"4.1.1. Definitions","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Behavioral-Equivaleence--Definitions"}});